-- Cross-Class AA Training (Tome) system - NMS merge
-- Generated from Ascendant-Server database package. Additive only (INSERT IGNORE).
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `aa_custom_mapping` (
  `original_aa_id` int(11) NOT NULL COMMENT 'Original AA ability ID',
  `universal_aa_id` int(11) NOT NULL COMMENT 'Universal grant-only AA ability ID',
  `aa_name` varchar(255) NOT NULL COMMENT 'AA name for reference',
  `tome_item_id` int(11) DEFAULT NULL COMMENT 'Translated tome item ID (fill later)',
  `tier` tinyint(1) DEFAULT NULL COMMENT 'Tome tier: 1=Greater, 2=Exalted, 3=Ascendant',
  `original_classes` int(11) NOT NULL COMMENT 'Original class bitmask for reference',
  `notes` varchar(255) DEFAULT NULL COMMENT 'Optional notes',
  `illegible_tome_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`original_aa_id`),
  UNIQUE KEY `universal_aa_id` (`universal_aa_id`),
  KEY `tome_item_id` (`tome_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Maps original AAs to universal versions for tome system';

